<?php /** The days of the site (screen sales-day-list). Data: rows, total, page, from, to, due, seesCost, mayRun, mayUpload, highlight, notice */ ?>
<?= view('shared/header.php', ['id' => 'sales-day-list', 'title' => 'Sales by day', 'crumbs' => [['Home', '/'], ['Sales by day', null]], 'action' => $mayUpload ? hx_link('/sales/upload', '<i class="feather-upload me-1"></i>Upload a POS file', 'btn btn-primary btn-touch', 'id="sales-day-list-upload"') : '']) ?>
<div class="main-content" id="sales-day-list-content">
    <?= view('shared/notice.php', ['notice' => $notice]) ?>
    <form method="get" action="/sales/" class="card mb-3" id="sales-day-filters" hx-get="/sales/" hx-target="#page-content" hx-push-url="true"><div class="card-body d-flex flex-wrap gap-2 align-items-center">
        <label class="fs-12" for="sales-day-from">From</label><input type="date" name="from" id="sales-day-from" class="form-control btn-touch w-auto" value="<?= e($from) ?>"><label class="fs-12" for="sales-day-to">to</label><input type="date" name="to" id="sales-day-to" class="form-control btn-touch w-auto" value="<?= e($to) ?>">
        <button type="submit" class="btn btn-light-brand btn-touch" id="sales-day-go">Show</button></div></form>
    <?php if ($due !== [] && $mayRun): ?><div class="card mb-3 border-warning" id="sales-day-due"><div class="card-body d-flex flex-wrap gap-2 align-items-center"><span class="fs-12 fw-semibold"><?= count($due) ?> day<?= count($due) === 1 ? '' : 's' ?> due for depletion:</span>
        <?php foreach ($due as $d): ?><form method="post" action="/sales/runs/run.php" hx-post="/sales/runs/run.php" hx-target="#flash" class="d-inline"><?= csrf_field() ?><input type="hidden" name="business_date" value="<?= e($d['business_date']) ?>"><button type="submit" class="btn btn-sm btn-warning btn-touch" id="sales-day-due-<?= e($d['business_date']) ?>"><?= $d['run_id'] === null ? 'Deplete' : 'Re-run' ?> <?= e(format_date($d['business_date'])) ?></button></form><?php endforeach; ?></div></div><?php endif; ?>
    <?php if ($rows === []): ?><div class="card" id="sales-day-empty"><div class="card-body empty-state"><span class="avatar-text avatar-lg rounded"><i class="feather-pie-chart"></i></span><div><div class="fw-semibold">No sales between <?= e(format_date($from)) ?> and <?= e(format_date($to)) ?></div><div class="fs-12 text-muted">Upload the POS's export, or let a scheduled source pull.</div></div></div></div>
    <?php else: ?><div class="card"><div class="card-body p-0"><div class="table-responsive"><table class="table table-sm mb-0 fs-12" id="sales-days-table">
        <thead><tr><th>Day</th><th class="text-end">Checks</th><th class="text-end">Covers</th><th class="text-end">Net</th><th class="text-end">Comps</th><th class="text-end">Voids</th><th>Run</th><th class="text-end">Depleted</th><th></th></tr></thead><tbody>
        <?php foreach ($rows as $d): $date = (string) $d['business_date']; ?><tr id="day-row-<?= e($date) ?>" class="<?= in_array($date, $highlight, true) ? 'table-success' : '' ?>">
            <td><?= hx_link('/sales/' . $date, e(format_date($date)), 'fw-semibold', 'id="day-link-' . e($date) . '"') ?></td><td class="text-end"><?= (int) $d['checks'] ?></td><td class="text-end"><?= (int) $d['covers'] ?></td><td class="text-end"><?= e(ri_money($d['net'])) ?></td><td class="text-end"><?= e(ri_money($d['comps'])) ?></td><td class="text-end"><?= e(ri_money($d['voids'])) ?></td>
            <td><span class="badge <?= pos_chip($d['run_status']) ?>" id="day-run-<?= e($date) ?>"><?= e($d['run_status'] ?? 'none') ?><?= $d['run_status'] === 'partial' ? ' — unmapped ' . ((int) $d['lines_unmapped'] + (int) $d['modifiers_unmapped']) : '' ?></span><?= $d['due'] && $d['run_id'] !== null ? ' <span class="badge bg-soft-warning text-warning">due</span>' : '' ?></td>
            <td class="text-end" id="day-value-<?= e($date) ?>"><?= $d['run_id'] === null ? '' : money($seesCost && $d['run_value'] !== null ? (string) $d['run_value'] : null) ?></td>
            <td class="text-end"><?php if ($mayRun && ($d['run_id'] === null || $d['due'])): ?><form method="post" action="/sales/runs/run.php" hx-post="/sales/runs/run.php" hx-target="#flash" class="d-inline"><?= csrf_field() ?><input type="hidden" name="business_date" value="<?= e($date) ?>"><button type="submit" class="btn btn-sm btn-light btn-touch" id="day-run-btn-<?= e($date) ?>"><?= $d['run_id'] === null ? 'Deplete' : 'Re-run' ?></button></form><?php endif; ?></td></tr><?php endforeach; ?>
    </tbody></table></div></div></div>
    <?php if ($total > POS_PAGE): ?><div class="d-flex justify-content-between align-items-center mt-2"><span class="fs-12 text-muted"><?= $total ?> days</span><div class="btn-group"><?php if ($page > 1): ?><?= hx_link('/sales/?' . http_build_query(['from' => $from, 'to' => $to, 'page' => $page - 1]), 'Previous', 'btn btn-light btn-touch') ?><?php endif; ?><?php if ($page * POS_PAGE < $total): ?><?= hx_link('/sales/?' . http_build_query(['from' => $from, 'to' => $to, 'page' => $page + 1]), 'Next', 'btn btn-light btn-touch') ?><?php endif; ?></div></div><?php endif; ?>
    <?php endif; ?>
</div>
